const rows = $input.all().map((i) => i.json);
const SESSION_GAP_MINUTES = 30;

const byConversation = {};
for (const row of rows) {
  (byConversation[row.conversation_id] ||= []).push(row);
}

const sessions = [];

for (const [conversationId, msgs] of Object.entries(byConversation)) {
  msgs.sort((a, b) => new Date(a.message_timestamp) - new Date(b.message_timestamp));

  let current = null;
  for (const m of msgs) {
    const ts = new Date(m.message_timestamp).getTime();
    if (!current || ts - current.lastTs > SESSION_GAP_MINUTES * 60 * 1000) {
      current = {
        conversation_id: conversationId,
        contact_name: m.contact_name,
        message_ids: [],
        lines: [],
        lastTs: ts,
        started_at: m.message_timestamp,
      };
      sessions.push(current);
    }
    current.message_ids.push(m.id);
    current.lines.push(`${m.is_support ? 'Suporte' : 'Cliente'}: ${m.message_text}`);
    current.lastTs = ts;
    current.ended_at = m.message_timestamp;
  }
}

// Descarta sessões com uma única mensagem (não há pergunta+resposta para aprender)
return sessions
  .filter((s) => s.lines.length >= 2)
  .map((s) => ({
    json: {
      conversation_id: s.conversation_id,
      contact_name: s.contact_name,
      message_ids: s.message_ids,
      transcript: s.lines.join('\n'),
      started_at: s.started_at,
      ended_at: s.ended_at,
    },
  }));

