const responses = $input.all().map((i) => i.json);
const sessions = $('Agrupar em Sessões de Atendimento').all().map((i) => i.json);

const output = [];

for (let i = 0; i < responses.length; i++) {
  const session = sessions[i];
  const body = responses[i];
  const content = body?.choices?.[0]?.message?.content || '{"items": []}';

  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    parsed = { items: [] };
  }

  const items = Array.isArray(parsed.items) ? parsed.items : [];
  const valid = items.filter((qa) => qa.question && qa.answer);

  if (valid.length === 0) {
    // Nenhuma dúvida relevante nessa sessão: marcar como processada mesmo assim,
    // para não reenviar o mesmo transcript para a IA todas as noites.
    output.push({ json: { _type: 'no_faq', message_ids: session.message_ids } });
    continue;
  }

  for (const qa of valid) {
    output.push({
      json: {
        _type: 'qa',
        question: String(qa.question).trim(),
        answer: String(qa.answer).trim(),
        category: qa.category || 'geral',
        confidence: qa.confidence || 'media',
        source_conversation_id: session.conversation_id,
        message_ids: session.message_ids,
      },
    });
  }
}

return output;

function esc(s) {
  if (s === null || s === undefined) return 'NULL';
  return "'" + String(s).replace(/'/g, "''") + "'";
}

const qa = $('Parsear Respostas da IA').item.json;
const embedding = $json.data[0].embedding;
const embeddingLiteral = `'[${embedding.join(',')}]'::vector`;

// Se já existir uma pergunta muito parecida (distância de cosseno < 0.15),
// só incrementa a frequência em vez de duplicar a linha na base.
const sqlQuery = `WITH sim AS (
  SELECT id, embedding <=> ${embeddingLiteral} AS distance
  FROM knowledge_base
  ORDER BY embedding <=> ${embeddingLiteral}
  LIMIT 1
),
upd AS (
  UPDATE knowledge_base kb
  SET frequency = kb.frequency + 1,
      last_seen = now()
  FROM sim
  WHERE kb.id = sim.id AND sim.distance < 0.15
  RETURNING kb.id
)
INSERT INTO knowledge_base (question, answer, category, confidence, frequency, embedding, source_conversation_id)
SELECT ${esc(qa.question)}, ${esc(qa.answer)}, ${esc(qa.category)}, ${esc(qa.confidence)}, 1, ${embeddingLiteral}, ${esc(qa.source_conversation_id)}
WHERE NOT EXISTS (SELECT 1 FROM upd)
  AND NOT EXISTS (SELECT 1 FROM sim WHERE sim.distance < 0.15);`;

return {
  json: {
    ...qa,
    sql_query: sqlQuery,
  },
};
